import{_ as t}from"./chunks/defdd2f4680f96492ad6.Mu3dm5Mc.js";import{_ as o,o as i,c as a,a6 as n}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"If You Feel Lost — Understand These 3 Phases Of Life","description":"","frontmatter":{"title":"If You Feel Lost — Understand These 3 Phases Of Life","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/if-you-feel-lost-understand-these-3-phases-of-life.md","filePath":"en/letters/if-you-feel-lost-understand-these-3-phases-of-life.md"}'),s={name:"en/letters/if-you-feel-lost-understand-these-3-phases-of-life.md"};function r(l,e,h,u,d,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="if-you-feel-lost-—-understand-these-3-phases-of-life" tabindex="-1">If You Feel Lost — Understand These 3 Phases Of Life <a class="header-anchor" href="#if-you-feel-lost-—-understand-these-3-phases-of-life" aria-label="Permalink to &quot;If You Feel Lost — Understand These 3 Phases Of Life&quot;">​</a></h1><p>Dan Koe · 2022-05-02 · <a href="https://thedankoe.com/letters/if-you-feel-lost-understand-these-3-phases-of-life/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/if-you-feel-lost-understand-these-3-phases-of-life">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/X47wVjXWW4M?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><a href="https://open.spotify.com/embed/episode/2MaWDuIu1vAoNqqqm9f5Yv?si=0a769b7296ac4020&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>It has always felt that my life unfolded in phases. In one phase, I felt lost. In another, pinned to my desk. Surging with energy. Deep in the flow state. Building out my future. In another phase, I was going through the motions, but with enjoyment.</p><p>The silly thing is that I had never felt this way while in high school or college. When teachers and employers directed my attention. The cyclical nature of sovereign living only came into play when I had to manage my goals. When I had to master my attention in relation to where I wanted to go in life.</p><p>The phases of being lost were the most destructive, yet most enlightening. Fumbling around in the dark, hoping to find a candle. Finding one. Watching it die out. Finding another and hoping it guides you to the next one before the darkness collapses once again.</p><p>Through awareness and the intention to improve, these cycles have become less destructive.</p><p>I could only imagine how some others must feel. Not knowing how to leverage those periods of feeling lost — when, in fact, you are only preparing for the next round of heat.</p><p>Like a sauna. Don’t fight it. <em>Let it purify you.</em></p><h2 id="the-3-drivers-of-progress" tabindex="-1">The 3 Drivers Of Progress <a class="header-anchor" href="#the-3-drivers-of-progress" aria-label="Permalink to &quot;The 3 Drivers Of Progress&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>The 3 Drivers Of Progress</p><p>When you commit to building a life according to your goals — as opposed to someone else’s — there are 3 drivers of progress. Meaning if you are engaged — or conscious — of these phases, you are making progress toward a better life.</p><p>These phases occur for everyone but are the most devastating for those that aren’t doing what they enjoy. For those that followed someone else’s path instead of blazing their own. Conditioned for a repetitive future since childhood.</p><p>Understanding these phases will help you identify where you are at in your journey, what you can do about it, and how to make accurate decisions.</p><p><strong>The 3 drivers of progress are:</strong></p><ol><li>Intensity</li><li>Consistency</li><li>Curiosity</li></ol><p>These come in cycles. Phases. One leads to another. They are inevitable cycles of life. Ebb and flow. Wu wei. Push pull. The secret is to let go. Let these cycles happen as they will. Flow with the river. Fighting it will only keep you trapped in that phase of life until you learn the lesson it is trying to teach you.</p><p>Intensity is for building. Consistency is for maintaining. Curiosity is for exploring.</p><p>These are not only life cycles, but year, month, week, and day cycles. We will be diving into the macro perspective in this post. While we are at it, can you start to become aware of these cycles in your day-to-day life?</p><p><em>Here’s how you navigate them:</em></p><h3 id="exploring-the-unknown" tabindex="-1">Exploring The Unknown <a class="header-anchor" href="#exploring-the-unknown" aria-label="Permalink to &quot;Exploring The Unknown&quot;">​</a></h3><blockquote><p>“When you walk to the edge of all the light you have and take that first step into the darkness of the unknown, you must believe that one of two things will happen. There will be something solid for you to stand upon or you will be taught to fly.” – Patrick Overton</p></blockquote><p>We will start with the curiosity phase as many people misperceive it. This is the phase that people get trapped in for life. Infinite room for improvement, <em>but keeping a 50-foot distance from the edge of their comfort zone.</em></p><p><strong>Life is a series of experiments.</strong> Nobody — not a single soul — has or ever will have it all figured out. The unknown is a land of infinite opportunity. Yet most people perceive it as a land of immense risk.</p><p>Side note: risk, as with everything else, is a label. A fabricated concept that implies a reward. The 1% of top performers perceive risk for what it is, <em>a part of life</em>. The 99% of under-performers perceive risk for what it does, destroys their bubble of familiarity. <em>Scary</em>.</p><p>The curiosity phase is tricky. It doesn’t seem like exploration. It seems like you are floating in space. No routine to ground yourself in. No sense of direction in life. Halfway between “I want to do this for the rest of my life!” and “Who would do this for the rest of their life?”</p><p>We must adopt the mindset of an explorer. Slashing through the jungle in search for a new life-changing discovery. Exploring the unknown is the real-world manifestation of “throwing sh*t at a wall and seeing what sticks.”</p><p>It takes intuition, surrender, and acceptance to navigate this phase with ease — but there are ways to navigate it more effectively. Try this:</p><ul><li>Write out 20 interests you have</li><li>Make a note of related interests (intersections)</li><li>Immerse yourself in information related to those</li><li>Read books, listen to podcasts, follow leaders in that space</li><li>Connect the dots and understand the real world utility</li><li>Teach what you have learned to understand it better</li></ul><p>By the end of it all, you gain a deeper understanding of the direction you must move in. Your neurobiology — the feeling of excitement — will hint at passion. Educate yourself along your journey in the unknown. Education shines the light of awareness on the map of the unknown. Invest your time in free content. <a href="https://join.modernmastery.co/" target="_blank" rel="noreferrer">Invest your money in the teachings of those you aspire to be like</a> (courses or coaching).</p><p>The curiosity phase is for exploration, experimentation, and making new discoveries. Those new discoveries lead you down a path that you want to go down — not the one someone else wants you to go down. This requires you to be in touch with your intuition — your neurobiology — and let curiosity be your intrinsic driver. It is a time for testing new interests, gauging their utility, and eventually connecting the dots. This leads to immense clarity that launches you into the next phase.</p><h3 id="building-a-better-future-—-fast" tabindex="-1">Building A Better Future — Fast <a class="header-anchor" href="#building-a-better-future-—-fast" aria-label="Permalink to &quot;Building A Better Future — Fast&quot;">​</a></h3><p>The intensity phase is for building a project related to your curiosities. When the clarity hits — mornings, nights, and days are a blur of trying to find the time to get things done as fast as possible. Nothing will stop you from blazing your trail. Focus is seamless. Flow seems to last all day. You don’t even need your precious to-do app to keep you on track.</p><p>This phase comes after the curiosity phase. It occurs when everything clicks. You make the new discovery, have a burst of clarity, and develop a strategy that will launch you to new heights. You can already <em>feel</em> yourself in your future shoes. Who you are and who you want to become merge into one. You are that person. You are just waiting for time to catch up.</p><blockquote><p>Intensity clarifies. It creates not only momentum, but also the pressure you need to feel either friction, or fulfillment. — Marcus Buckingham</p></blockquote><p>The building phase is for turning curiosity into obsession. It is for brewing the neurochemical cocktail that launches you into the flow state. It is for cultivating passion and purpose while building towards autonomy and mastery. This is where you build out your future. Personal freedom. Self-actualization. This phase is best used on a project with high potential profitability. It can start as a hobby — and can remain a hobby — but autonomy is necessary if you want to continue down this path.</p><p>Towards the end of this phase, you must systemize if you want to maintain your progress.</p><h3 id="consistency-compounds" tabindex="-1">Consistency Compounds <a class="header-anchor" href="#consistency-compounds" aria-label="Permalink to &quot;Consistency Compounds&quot;">​</a></h3><p>At the end of the intensity phase, you reach a new baseline. Mental, physical, spiritual, financial, whatever it may be. If you don’t maintain this baseline, you will hit a new low. Again, this is a cycle. You don’t have to fall back into a curiosity phase just to feel lost again.</p><p>Consistency is best navigated with systems. These systems should revolve around the fundamentals. The lever-moving actions that result in growth. Bake these fundamentals into your routines, automate them if you can, and delegate what you hate doing.</p><p>Again, take out pen and paper, or download my planner:</p><ul><li>Note your lever-moving goal-oriented tasks</li><li>Schedule time blocks for executing on those</li><li>Avoid distractions and get into a deep work routine</li><li>Do this when your energy is highest</li><li>Reflect often and delegate what you don’t like to tech or VAs</li></ul><p>By building out proper life and business systems, you can maintain a full-time income with 2-4 hours of focused work. No-code tech advancements have reduced the workload of solopreneurs. Digital product and service creators have a luxury that many can’t fathom. You can only decrease your work times by automating or delegating tasks. Employees are the ones that get delegated tasks.</p><p>Once you feel stable, you can maintain your progress and take the plunge into another curiosity phase. Explore the unknown, self-educate to find your way, and let new discoveries launch you into a cycle of intensity. (Bonus points if you build on top of what you’ve already built — that’s leverage.)</p><h3 id="macro-micro-phases" tabindex="-1">Macro &amp; Micro Phases <a class="header-anchor" href="#macro-micro-phases" aria-label="Permalink to &quot;Macro &amp; Micro Phases&quot;">​</a></h3><p>Once you have consciously experienced these phases, they become more predictable. You can navigate them more efficiently. You can predict what is going to happen and ease your worries about the future.</p><p>The thing is, <em>these phases do not only exist in the macro.</em> They exist in the micro. You can use your understanding of these phases to craft a sustainable routine. For example, I:</p><ul><li>Build for the first 2 hours of the morning (intensity)</li><li>Maintain for 2 hours after that (consistency)</li><li>Explore in my afternoons (curiosity)</li></ul><p><a href="https://thedankoe.com/the-3-habit-morning-routine-to-end-procrastination/" target="_blank" rel="noreferrer">This is baked into my schedule.</a> A well designed lifestyle. Micro phases within macro phases. It is a balance of segmenting your time and knowing when to pivot.</p><p>But we can talk about that at another time. We will dive deep into lifestyle design in a later post.</p><p>If you want weekly updates on my articles and my top 3 life &amp; business tips of the week, <a href="https://links.thedankoe.com/#letter" target="_blank" rel="noreferrer">subscribe to The Koe Letter</a>.</p>',53)])])}const m=o(s,[["render",r]]);export{y as __pageData,m as default};
